-- Generated by scripts/build-ai-solution-actions-catalog.ts.
-- Apply core first, deploy ask-bob AND bob-worker, then activate this publication.
begin;
do $server_bound_edits_catalog$
declare contracts jsonb:=$bound_edit_contracts$[
  {
    "name": "read_solution_context",
    "description": "Read server-bound choices for solution actions: existing solutions, selected solutions, project/Area scopes, measurements or images. Reuse returned refs unchanged. Scopes include the exact current selection. Images are metadata only; visual interpretation still requires opening pixels. next_ref continues this exact filter.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "resource": {
          "type": "string",
          "enum": [
            "solutions",
            "selected_solutions",
            "scopes",
            "measurements",
            "images"
          ]
        },
        "query": {
          "type": [
            "string",
            "null"
          ]
        },
        "next_ref": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "resource",
        "query",
        "next_ref"
      ]
    }
  },
  {
    "name": "create_solution_alternative",
    "description": "Create an explicitly new alternative, never a repair for a failed edit. Choose a scope_ref from read_solution_context. To reuse existing data, choose base_ref from solutions and provide only differences; its measurements, image links and design decisions are copied automatically. With base_ref=null, provide at least /title and /description. Changes use edit_project_record content paths; item identities are generated by the server. Creating does not select the alternative. Read the saved alternative before selecting or editing it.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "scope_ref": {
          "type": "string"
        },
        "base_ref": {
          "type": [
            "string",
            "null"
          ]
        },
        "changes": {
          "type": "array",
          "minItems": 1,
          "maxItems": 40,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "op": {
                "type": "string",
                "enum": [
                  "set",
                  "append_text",
                  "remove"
                ]
              },
              "path": {
                "type": "string"
              },
              "value_json": {
                "type": [
                  "string",
                  "null"
                ],
                "description": "JSON-encoded new value. null only for remove. append_text appends the decoded string verbatim."
              }
            },
            "required": [
              "op",
              "path",
              "value_json"
            ]
          }
        },
        "reason": {
          "type": "string"
        },
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "scope_ref",
        "base_ref",
        "changes",
        "reason",
        "request_quote"
      ]
    }
  },
  {
    "name": "select_solution_alternative",
    "description": "Select an existing solution_ref for a scope_ref read in this turn. The server binds both revisions; changed records require a new read. This selects design intent, never measured truth or structural approval. It does not create a solution.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "solution_ref": {
          "type": "string"
        },
        "scope_ref": {
          "type": "string"
        },
        "reason": {
          "type": "string"
        },
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "solution_ref",
        "scope_ref",
        "reason",
        "request_quote"
      ]
    }
  },
  {
    "name": "change_solution_evidence",
    "description": "Change only an explicit evidence link on a solution_ref from this read. Prefer selected_solutions to advance that selected scope atomically. add_measurement binds the exact measured/provided/estimated/unknown value without retyping it; remove_measurement uses its zero-based index in the returned measurements. set_primary_image and add_design_reference use an image source_ref; clear_primary_image and remove_design_reference use null. Removal uses item_index, addition uses null. Design reference addition requires role and note; all other actions require role/note=null. Preserve other links and content. Metadata never proves image interpretation. Re-read after saving.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "solution_ref": {
          "type": "string"
        },
        "action": {
          "type": "string",
          "enum": [
            "add_measurement",
            "remove_measurement",
            "set_primary_image",
            "clear_primary_image",
            "add_design_reference",
            "remove_design_reference"
          ]
        },
        "source_ref": {
          "type": [
            "string",
            "null"
          ]
        },
        "item_index": {
          "type": [
            "integer",
            "null"
          ]
        },
        "role": {
          "type": [
            "string",
            "null"
          ],
          "enum": [
            "appearance",
            "layout",
            "context",
            null
          ]
        },
        "note": {
          "type": [
            "string",
            "null"
          ]
        },
        "reason": {
          "type": "string"
        },
        "request_quote": {
          "type": "string"
        }
      },
      "required": [
        "solution_ref",
        "action",
        "source_ref",
        "item_index",
        "role",
        "note",
        "reason",
        "request_quote"
      ]
    }
  }
]$bound_edit_contracts$::jsonb;
 policies jsonb:=$bound_edit_policies$[
  {
    "name": "read_solution_context",
    "description": "Read bound alternatives, scopes and sources",
    "how_to": "Choose returned refs; do not construct IDs or copy source values. Image metadata is not inspected pixels.",
    "schema_version": 1,
    "always_load": true,
    "preload_phases": [],
    "active": true
  },
  {
    "name": "create_solution_alternative",
    "description": "Create an explicit new alternative from content changes",
    "how_to": "Read scope and optional base first. Copy known content automatically; never create as recovery from a failed edit. Selection is separate.",
    "schema_version": 1,
    "always_load": true,
    "preload_phases": [],
    "active": true
  },
  {
    "name": "select_solution_alternative",
    "description": "Select a read solution in a read scope",
    "how_to": "Read the current scope and latest alternative; the server binds revisions. Changed state requires reconsideration.",
    "schema_version": 1,
    "always_load": true,
    "preload_phases": [],
    "active": true
  },
  {
    "name": "change_solution_evidence",
    "description": "Change one source link while preserving other solution data",
    "how_to": "Read selected_solutions and source choices. Bind existing measurement truth and exact revision; preserve all unrelated content. Re-read after saving.",
    "schema_version": 1,
    "always_load": true,
    "preload_phases": [],
    "active": true
  }
]$bound_edit_policies$::jsonb;
 append jsonb:=$bound_edit_append$[
  {
    "key": "tools.save_project_solution",
    "text": " Superseded for fresh manifests by create_solution_alternative for explicit new alternatives, edit_project_record for existing content, and change_solution_evidence for links. Read existing data; do not transcribe database fields."
  },
  {
    "key": "tools.select_project_target",
    "text": " Superseded for fresh manifests by read_solution_context and select_solution_alternative. The runtime binds the selected solution and destination scope revisions."
  }
]$bound_edit_append$::jsonb;
 patch jsonb; policy jsonb; prior shared.ai_prompt_versions; template shared.ai_prompt_versions;
 prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 select v.* into template from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.save_project_description';
 if not found then raise exception 'bound_edit_template_missing'; end if;
 for patch in select value from jsonb_array_elements(contracts) loop
  select value into policy from jsonb_array_elements(policies) where value->>'name'=patch->>'name';
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.'||(patch->>'name');
  if not found then
   insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind)
    values('bob','tools.'||(patch->>'name'),policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
   prior:=template;
  else prompt_uuid:=prior.prompt_id;
  end if;
  definition:=prior.definition||patch||jsonb_build_object('handler',patch->>'name','required_parameters',patch#>'{parameters,required}','optional_parameters','[]'::jsonb,'additional_description',policy->>'how_to');
  definition:=jsonb_set(definition,'{envelope,schema_version}','1'::jsonb);
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,next_version,'tool_contract',1,jsonb_build_object('publication','server-bound-solution-actions','server_fields',case when patch->>'name'<>'read_solution_context' then ' ["request_quote"]'::jsonb else '[]'::jsonb end),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object('tools.'||(patch->>'name'),version_uuid);
 end loop;
 for patch in select value from jsonb_array_elements(append) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key';
  if not found then raise exception 'bound_edit_legacy_contract_missing'; end if;
  definition:=jsonb_set(prior.definition,'{additional_description}',to_jsonb(coalesce(prior.definition->>'additional_description','')||(patch->>'text')));
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','server-bound-solution-actions'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' for update of p;
 if not found then raise exception 'bound_edit_toolbox_missing'; end if;
 definition:=prior.definition;
 for policy in select value from jsonb_array_elements(policies) loop
  insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
   values(policy->>'name',policy->>'description',policy->>'how_to',(policy->>'schema_version')::integer,(policy->>'always_load')::boolean,array(select jsonb_array_elements_text(policy->'preload_phases')),(policy->>'active')::boolean)
   on conflict(name) do nothing;
  if not exists(select 1 from jsonb_array_elements(definition->'catalog') r where r->>'name'=policy->>'name') then
   definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
  end if;
  if not definition->'contract_keys'?('tools.'||(policy->>'name')) then
   definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.'||(policy->>'name')));
  end if;
  definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when shelf->>'label'='Project records and memory' and not shelf->'tools'?(policy->>'name') then jsonb_set(shelf,'{tools}',shelf->'tools'||jsonb_build_array(policy->>'name')) else shelf end) from jsonb_array_elements(definition->'shelves') shelf));
 end loop;
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','server-bound-solution-actions'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $server_bound_edits_catalog$;
commit;
